// Frontend fetching example showing different methods on the EXACT SAME URL!

const url = 'https://api.store.com/products/123';

// 1. READ: Tell me about Product 123
fetch(url, { method: 'GET' });

// 2. UPDATE: Change the price of Product 123
fetch(url, { 
  method: 'PUT', 
  body: JSON.stringify({ price: 9.99 }) 
});

// 3. DELETE: Remove Product 123 from the store
fetch(url, { method: 'DELETE' });
